CREATE TABLE IF NOT EXISTS public.asset_provenance (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, project_id UUID, scene_id UUID, kind TEXT, type TEXT, provider TEXT, model TEXT, prompt TEXT, seed TEXT, asset_url TEXT, license TEXT, license_url TEXT, cost_credits INTEGER DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.billing_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), event_id TEXT UNIQUE, provider TEXT, payload JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.channel_stats (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, snapshot_date DATE, metrics JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.characters (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, name TEXT, description TEXT, style TEXT, reference_image_url TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.learning_insights (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, kind TEXT, title TEXT, note TEXT, payload JSONB, youtube_video_id TEXT, safety_score INTEGER, monetization_status TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.music_tracks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), provider TEXT, provider_track_id TEXT, title TEXT, artist TEXT, mood TEXT, duration_secs INTEGER, preview_url TEXT, download_url TEXT, license TEXT, license_url TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.outlier_videos (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, project_id UUID, youtube_id TEXT, title TEXT, channel_title TEXT, view_count BIGINT, ctr NUMERIC, retention NUMERIC, outlier_score NUMERIC, patterns JSONB, source TEXT, published_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.plans (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), slug TEXT UNIQUE, name TEXT, price_cents INTEGER DEFAULT 0, credits INTEGER DEFAULT 0, features JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.publish_jobs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, project_id UUID, video_job_id UUID, thumbnail_id UUID, title TEXT, description TEXT, tags TEXT[], privacy TEXT DEFAULT 'private', made_for_kids BOOLEAN DEFAULT false, scheduled_for TIMESTAMPTZ, status TEXT NOT NULL DEFAULT 'draft', safety_score INTEGER, safety_override BOOLEAN DEFAULT false, approved_at TIMESTAMPTZ, approved_by UUID, published_at TIMESTAMPTZ, youtube_video_id TEXT, youtube_url TEXT, error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.referrals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), referrer_id UUID NOT NULL, referee_id UUID, code TEXT, status TEXT DEFAULT 'pending', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.research_projects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, topic TEXT, language TEXT, niches TEXT[], created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.safety_scores (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, project_id UUID, score INTEGER, band TEXT, dimensions JSONB, issues JSONB, suggestions JSONB, model TEXT, version TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.seo_metadata (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, project_id UUID, video_job_id UUID, thumbnail_id UUID, titles JSONB, selected_title TEXT, description TEXT, tags TEXT[], hashtags TEXT[], chapters JSONB, status TEXT DEFAULT 'draft', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.subscriptions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, provider TEXT, external_id TEXT, plan_slug TEXT, status TEXT DEFAULT 'active', current_period_start TIMESTAMPTZ, current_period_end TIMESTAMPTZ, cancel_at_period_end BOOLEAN DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.thumbnails (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, project_id UUID, provider TEXT, model TEXT, text_overlay JSONB, image_url TEXT, selected BOOLEAN DEFAULT false, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.video_analytics (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, publish_job_id UUID, youtube_video_id TEXT, snapshot_date DATE, age_days INTEGER, metrics JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.video_ideas (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, project_id UUID, status TEXT DEFAULT 'new', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.youtube_api_cache (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID, cache_key TEXT, payload JSONB, expires_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.asset_provenance TO authenticated; GRANT ALL ON public.asset_provenance TO service_role;
GRANT SELECT, INSERT ON public.billing_events TO authenticated; GRANT ALL ON public.billing_events TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.channel_stats TO authenticated; GRANT ALL ON public.channel_stats TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.characters TO authenticated; GRANT ALL ON public.characters TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.learning_insights TO authenticated; GRANT ALL ON public.learning_insights TO service_role;
GRANT SELECT ON public.music_tracks TO authenticated; GRANT SELECT ON public.music_tracks TO anon; GRANT ALL ON public.music_tracks TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.outlier_videos TO authenticated; GRANT ALL ON public.outlier_videos TO service_role;
GRANT SELECT ON public.plans TO authenticated; GRANT SELECT ON public.plans TO anon; GRANT ALL ON public.plans TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.publish_jobs TO authenticated; GRANT ALL ON public.publish_jobs TO service_role;
GRANT SELECT, INSERT, UPDATE ON public.referrals TO authenticated; GRANT ALL ON public.referrals TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.research_projects TO authenticated; GRANT ALL ON public.research_projects TO service_role;
GRANT SELECT, INSERT ON public.safety_scores TO authenticated; GRANT ALL ON public.safety_scores TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.seo_metadata TO authenticated; GRANT ALL ON public.seo_metadata TO service_role;
GRANT SELECT, INSERT, UPDATE ON public.subscriptions TO authenticated; GRANT ALL ON public.subscriptions TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.thumbnails TO authenticated; GRANT ALL ON public.thumbnails TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.video_analytics TO authenticated; GRANT ALL ON public.video_analytics TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.video_ideas TO authenticated; GRANT ALL ON public.video_ideas TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.youtube_api_cache TO authenticated; GRANT ALL ON public.youtube_api_cache TO service_role;
ALTER TABLE public.asset_provenance ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.billing_events ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.channel_stats ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.characters ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.learning_insights ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.music_tracks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.outlier_videos ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.plans ENABLE ROW LEVEL SECURITY;
